import { DETAIL_SCHEMA } from '../../../shared/building-model-schema.js';   // the ONE declaration of a detail kind — the screen floors below are read off it rather than restated
import { AUTHORED_MODELS } from '../../../shared/building-models.js';   // generated by `npm run models:bake` from content/building_models/ — see drawAuthoredModel
import { paintFauna, faunaWorldFaces, faunaWorldFacesInto, faunaHasFar, faunaPoolReset, faunaFaces, faunaCountPainted, faunaDotColour, faunaDotPx, faunaSpanTiles, FAUNA_BEAT_STEPS, FAUNA_TILE, FAUNA_LOD_FAR, FAUNA_LOD_COARSE, FAUNA_LOD_GLYPH } from './fauna3d.js';
