import { flocksNear, flockState, flockClearance, gooseHabitat, speciesAt, habitatState, callsIn, spOf, placeOf, gullsAshore, hawkStoop, lostTo, alarmAt, flockEdgeHeading, skeinSlot, perchedNow, perchesHigh, flockSize, flockPeriod, groundSpot, GOOSE_FLAP_HZ, U_GROUND, GOOSE_SETTLE_MS } from '../../../shared/birds.js';
import { CAB_VIEW_TUNE } from '../../../shared/cab-render-tune.js';   // the ground camera's load-shedding numbers — shared with the trucking regress, which asserts they fit inside CAB_RADIUS
