      g.beginPath(); g.moveTo(0, S * 0.5); g.lineTo(S, S * 0.5); g.stroke();
      g.strokeStyle = 'rgba(255,255,255,0.07)';
      g.beginPath(); g.moveTo(0, S * 0.5 - 1); g.lineTo(S, S * 0.5 - 1); g.stroke();
