    const l2 = bx * bx + by * by;
    const t = l2 < 1e-9 ? 0 : clamp(((gx - ax) * bx + (gy - ay) * by) / l2, 0, 1);
    const dx = gx - (ax + t * bx), dy = gy - (ay + t * by);
