  // must NOT flip the memory, or the deep-off-map fallback would paint ocean once you've passed it.
  const centerLand = cc ? ((cc[3] > 0.5 && ((ci - R) + wcy) <= BAY_SHORE_Y) ? 0 : 1) : (st.offLand ?? 0);
