      if (arid) { const j = vnoise2(awx * 0.21, awy * 0.21) - 0.5; col = [clamp(col[0] + j * 46, 40, 210), clamp(col[1] + j * 30, 30, 190), clamp(col[2] + j * 22, 24, 170)]; }
      const shade = reliefShade(awx, awy, litX, litY, arid);
