const BLDG_H = { uptown: 0.36, civic: 0.21, citycore: 0.18, marquee: 0.22, freight: 0.14, industrial: 0.26, infra: 0.32, ruins: 0.16, oldcoldwater: 0.11, docks: 0.17, __nofly: 0.6 };

// ── 3-D building standard ─────────────────────────────────────────────────────
// STANDARD: every building_type gets a 3-D representation here — an archetype (which
// drawBuilding silhouette to extrude, reusing the biome archetypes) plus a height.
// The map-window cell carries `bt` (building_type, from state.js mapWindow); the
// windshield keys the flying-over 3-D shape off it. When a NEW building_type is
// introduced, add it here AND to BUILDING_TYPE_ICON (server/engine/world.js, the 2-D
// map footprint) so a building reads consistently in both views. `default` is the
// fallback: an unknown type — or one whose entry hasn't loaded — still extrudes a
// believable mid-rise instead of vanishing. Keep the archetype in the BLDG_H key set.
const BLDG_TYPE_3D = {
  // A haulage shed: freight-district mass, and low — a rig has to get in and out of it.
  truck_depot:      { a: 'freight',    h: 0.15 },
  // Low, both of them, and for the same reason the depot above is: everything that matters about
  // either building happens at the height of a cab window.
  weigh_station:    { a: 'freight',    h: 0.11 },
  vehicle_pound:    { a: 'freight',    h: 0.09 },
  corporate_office: { a: 'uptown',    h: 0.40 }, // glass towers
  office:           { a: 'uptown',    h: 0.36 }, // alias — see TYPE_MODEL note
  civic:            { a: 'civic',     h: 0.22 },
  grocery:          { a: 'citycore',  h: 0.15 },
  hotel:            { a: 'uptown',    h: 0.34 },
  apartment:        { a: 'citycore',  h: 0.28 },
  residential:      { a: 'citycore',  h: 0.18 },
  shop:             { a: 'citycore',  h: 0.15 },
  diner:            { a: 'citycore',  h: 0.12 },
  bar:              { a: 'marquee',   h: 0.15 },
  club:             { a: 'marquee',   h: 0.18 },
  studio:           { a: 'infra',     h: 0.22 },
  police:           { a: 'civic',     h: 0.22 },
  clinic:           { a: 'civic',     h: 0.22 },
  power:            { a: 'industrial', h: 0.34 },
  hangar:           { a: 'freight',   h: 0.14 },
  gun_shop:         { a: 'citycore',   h: 0.13 }, // squat riveted blockhouse
  blade_shop:       { a: 'citycore',   h: 0.12 }, // low forge shed, chimney short
  casino:           { a: 'marquee',    h: 0.17 }, // neon-drowned gambling house
  fence:            { a: 'citycore',   h: 0.13 }, // grimy pawnshop
  chem_supply:      { a: 'industrial', h: 0.16 }, // drum-stacked depot
  // Marrow Street — the workaday downtown strip. Low-rise throughout except the
  // department store, which is the only thing on the street with four floors.
  dept_store:       { a: 'citycore',    h: 0.30 }, // Adequate! — the strip's anchor
  hardware:         { a: 'citycore',    h: 0.13 }, // Nuts to That, stock under the awning
  bathhouse:        { a: 'citycore',    h: 0.14 }, // Lather & Lye, venting steam
  noodle_bar:       { a: 'oldcoldwater', h: 0.09 }, // Oyelaran's — one storey, open front
  outfitter:        { a: 'citycore',    h: 0.13 }, // Layers
  bodega:           { a: 'oldcoldwater', h: 0.11 }, // Bodega Vu, on the Ironside corner
  butcher:          { a: 'oldcoldwater', h: 0.10 }, // Meat Your Maker, single storey with a flat roof
  church:           { a: 'oldcoldwater', h: 0.16 }, // St Garneau's, twin towers over a barrel-vaulted nave
  comic_shop:       { a: 'oldcoldwater', h: 0.13 }, // Mint Condition, on the last dry corner of Ironside
  // The Ascendant Stronghold (docs/proposals/ascendant-stronghold.md) — heights come from
  // flags.floors on each facade; these are the archetype/fallback if a model fails to load.
  asc_spire:        { a: 'uptown',     h: 0.50 },
  asc_gate:         { a: 'civic',      h: 0.12 },
  asc_clinic:       { a: 'civic',      h: 0.16 },
  asc_weave:        { a: 'industrial', h: 0.20 },
  asc_vats:         { a: 'industrial', h: 0.24 },
  asc_shrine:       { a: 'citycore',   h: 0.30 },
  ruins:            { a: 'ruins',     h: 0.16 }, // a wall/dam/shell — long and low, never a block
  default:          { a: 'citycore',  h: 0.22 }, // fallback when a type has no entry / fails to load
};
// The archetype + base height for a map cell: a building tile (has `bt`) renders its
// type's 3-D shape (or the fallback for an unknown type); a plain tile keeps its biome.
function bldgStyle(cell) {
  const s = cell && cell.bt ? (BLDG_TYPE_3D[cell.bt] || BLDG_TYPE_3D.default) : null;
  return s ? { arch: s.a, baseH: s.h } : { arch: cell && cell.biome, baseH: BLDG_H[cell && cell.biome] || 0.3 };
}

// ── Building height by STOREYS ────────────────────────────────────────────────
// Height comes from the building's real floor count, not a per-type slab: a 3-floor
// hotel is a mid-rise, a corporate office a tower, a corner shop a single storey.
// The server passes an authored floor override (cell.flr = flags.floors) when set;
// otherwise we fall back to a believable per-type default. FLOOR_Z is the world-z
// height of one storey — the whole thing still scales with the bldgH tuning knob so
// the ⚙ slider keeps working. This is the ONE height formula; buildingHeightZ (CFIT
// collision) and drawWorldObjects (render) both call floorHeight so what you see is
// exactly what you can hit.
// Floor counts nudged UP for the low-rise commercial/civic types: a 1-storey pancake in a
// dense ~50-year-future city reads wrong, so a corner shop is small-mixed-use, a soundstage
// a tall clear-span volume, a bar/club a couple of storeys. Raises BOTH the rendered mass and
// the CFIT collision ceiling (both key off floorsOf), so the taller look stays hittable.
// TYPE_FLOORS / FLOOR_Z now live in client/shared/skyline-scale.js — the cold
// open's closing flythrough renders the same skyline as a wireframe and cannot
// import this file to get them. Same numbers, one home.
// ── ⚠ THE ONE BUILDING WHOSE MASS IS A SHAPE, NOT A STOREY STACK ─────────────
// The depot bay (drawVehicleBay, below) is drawn at a FIXED height rather than extruded from a
// floor count, and it has to be: it is the one building with a camera inside it, and its eaves must
// clear the cab's eye (`eyeH: 0.12`) or the driver is looking over his own roof. A floor count
// cannot promise that — `bldgStretch` is a live dev-panel slider, so somebody dragging "Vert
// stretch" would put the roof back under the windscreen.
//
// So the numbers are here, next to the formula they are an exception to, and BOTH sides of the
// draw/collide contract are keyed off them: `floorHeight` answers with the shed's real ridge (so
// the render, the ground shadow, the occlusion pre-pass and `buildingHeightZ` all agree), and
// `floorsOf` answers with the storey count that ridge is WORTH (so the feet-based CFIT altitude
// lands on the same roof). Without the second half the shed drew at 0.43 and collided at 0.196 —
// an aircraft flew through the top two thirds of a building a truck cannot drive through the wall
// of. Change RIDGE and you must change BAY_FLOORS with it; the smoke asserts they stay in step.
const BAY = {
  HW: 0.47, HL: 0.47,           // half-width / half-depth — a shed fills its tile, setbacks are for shops
  WALL: 0.30, RIDGE: 0.43,      // eaves and ridge: a clear-span volume, ~1.8× the driver's eye at the eaves
  DOOR_W: 0.20, DOOR_H: 0.24,   // the opening: a door for a TRUCK, which is the whole read from the air
  LANE: 0.15,                   // half-width of the marked drive lane down the middle
};
// What the ridge is worth in storeys at the default tune (RIDGE / (FLOOR_Z × bldgH × bldgStretch)
// ≈ 0.43 / 0.196). A haulage shed as two-and-a-bit tall storeys ≈ 26 ft to the ridge, which is what
// an aircraft collides with and what `buildingRoofFt` reports.
const BAY_FLOORS = 2.2;
// The roof line at a point across the shed, in world-z: a straight gable from eaves to ridge, which
// is exactly the two pitches drawVehicleBay paints. `lx` is the local cross-shed coordinate.
const bayTopZ = (lx) => BAY.WALL + (BAY.RIDGE - BAY.WALL) * Math.max(0, 1 - Math.abs(lx) / BAY.HW);
const isBay = (cell) => cell && cell.mark === 'bay';
function floorsOf(cell) { return isBay(cell) ? BAY_FLOORS : floorsFor(cell && cell.bt, cell && cell.flr); }
// Deterministic building height for a cell: floors × per-storey, with a small stable
// jitter off the seed so same-type neighbours aren't a dead-flat skyline. A bay takes neither —
// every shed is the same shed, and a jittered one would collide off its own roofline.
function floorHeight(cell, seed) {
  if (isBay(cell)) return BAY.RIDGE;
  return floorsOf(cell) * FLOOR_Z * (0.9 + frac(seed) * 0.2) * RENDER_TUNE.bldgH * (RENDER_TUNE.bldgStretch || 1);
}

// Building footprint half-width (tile units) — a building fills most of its own tile. This
// is the SAME value the CFIT collision sweep reads (cockpit.js imports it) so a plane hits a
// tower's mass exactly where its base is drawn, not a tiny box at the tile centre. Scaled by
// the bldgFoot tuning knob at both the draw and the collision sites so they never drift.
// Defined in client/shared/skyline-scale.js and re-exported here, because
// cockpit.js's collision sweep imports it from this module. Live-tunable via the
// dev-panel "Bldg width" slider (RENDER_TUNE.bldgFoot).
export { BUILDING_FOOT };

// Deterministic building height (render world-z units) for a tile — the SAME value
// drawWorldObjects paints (line ~1419), exposed so the flight sim can collision-check the
// exact geometry that's on the glass. Returns 0 for tiles that carry no solid building to
// fly into: open air, bare apron/terrain of every kind, and the no-fly markers (the airspace
// system owns those, so we don't double-punish there) — only a real building tile (has `bt`)
// extrudes solid mass.
// `cell` is a map-window cell { kind, biome, bt, ... }; wx,wy are its WORLD tile coords.
export function buildingHeightZ(wx, wy, cell) {
  if (!cell) return 0;
  const k = cell.kind;
  // A rooftop pad (a `bt` building tile that also carries an airfield_id) keeps its
  // mass — the tower is still there to fly into; only bare field surfaces are clear.
  // `cell.self` used to zero this, and it is the third place the own-tile
  // assumption cost something. A tower does not stop having a roof because you
  // flew over it: this feeds modelTopAt, so the moment the Solenne became your
  // tile its pad height read 0 — which is why roofPadProximity dropped it (it
  // requires padFt > 0) at exactly the radius the catch arms at, and why the pad
  // never took an aircraft the way the Echelon's does. Bare fields are still
  // cleared by the `field && !bt` arm below, which is the case self was standing
  // in for.
  //
  // THE BIOME NEVER VETOES A BUILDING. The ground tint used to be able to zero a tower's
  // mass — a `bt` tile whose biome read water/parkland/badlands returned 0 — and that was
  // the fourth and last place a building stopped being solid without stopping being drawn.
  // It bit the whole 914/908 expansion: `districtBiome` has no arm for a `zone_district_*`
  // id and `zones` no longer carries a danger column, so every one of those 84 building
  // tiles falls to the 'badlands' default and was a ghost — no CFIT, and no roof for
  // `buildingRoofFtAt` to answer with, which is why the Solenne's pad drew no guidance
  // column and took no helicopter. `bt` is the whole question: a tile carries a building or
  // it doesn't, and the tint it sits on has nothing to say about it. The `field && !bt` arm
  // it replaces is subsumed — a bare apron has no `bt` either.
  if (!cell.bt || k === 'air' || k === 'nofly') return 0;
  const seed = (wx + 512) * 73 + (wy + 512) * 149;
  return floorHeight(cell, seed);
}

// Building roof altitude in FEET AGL — the COLLISION counterpart to buildingHeightZ (which is the
// render's stylised world-z). The shared source of truth between draw and collision is the FLOOR
// COUNT: the renderer extrudes floors into world-z for a pleasing skyline, but the camera's eye-height
// is a √-compressed function of altitude, so that world-z can't also be linear in real feet. So the
// sim collides in real feet straight off the floors — a 1-storey shop ≈ 12 ft, a 22-storey tower ≈
// 264 ft — which both reads sensibly and stops the old flat hz·600 from CFIT-ing you a third of a
// mile above a corner shop. Returns 0 for any tile with no solid building (reuses buildingHeightZ's gate).
// ── THE SIM'S OWN (fh, h), FOR ANYTHING THAT PREVIEWS A BUILDING ────────────
// A model arm takes a footprint half-width and a storey-stack height, and until the
// Modelshop existed the only caller was drawWorldObjects, which derives both from the
// tile. A preview that invents its own pair is previewing a building the game will never
// draw — so the formula is stated once, here, and the tool asks for it.
//
// Both terms carry the per-tile jitter (`frac(seed)`) deliberately: a real building is
// never exactly BUILDING_FOOT wide, and a preview that pretends otherwise hides the range
// an author's model actually has to survive. The RENDER_TUNE multipliers are in for the
// same reason — a tuning slider that moved the game and not the preview would make the
// preview a lie.
export function buildingScaleFor(floors, seed = 0) {
  return {
    fh: (BUILDING_FOOT + frac(seed + 2) * 0.06) * (RENDER_TUNE.bldgFoot || 1),
    h: Math.max(1, floors) * FLOOR_Z * (0.9 + frac(seed) * 0.2) * RENDER_TUNE.bldgH * (RENDER_TUNE.bldgStretch || 1),
  };
}

export const FT_PER_FLOOR = 12;   // realistic storey height (ft) — still the floors↔feet rule for anything that asks about STOREYS

// ── THE ALTITUDE AT WHICH THE EYE RISES ABOVE A DRAWN ROOF ──────────────────
//
// The renderer draws a building's top at a world-z. The camera's eye sits at
//
//     EH = eh + climbLift · √(altitude / 3000)
//
// so IN THE PICTURE you are above a roof exactly when EH exceeds that z. The curve is
// √-compressed on purpose — it is what lets a cockpit at two thousand feet still read the ground
// as tiles rather than a sheet — and collision was LINEAR in feet (storeys × 12, scaled by how far
// the model extrudes past its storey stack). A straight line and a square root agree at one height
// and nowhere else.
//
// ⚠ AND THEY DISAGREED IN BOTH DIRECTIONS, WHICH IS WHY NEITHER HALF LOOKED LIKE A BUG. Measured
// over all 113 named models: the Solenne cleared CFIT at 161 ft while the eye only rises above its
// drawn roof at 339 — so between those you fly straight through a tower that fills the windscreen,
// which is the report this came from. At the other end a shed collided to 30 ft when the eye is
// above it at 4, which is a hit on something the player can plainly see they are over, and the one
// thing the CFIT sweep's own rules say must never happen.
//
// Inverting the eye-height curve is the single conversion that makes "am I above it" the same
// question for the picture and for the sim. It is not a tuning constant and must not become one:
// it is the render curve read backwards, so a change to `eh` or `climbLift` moves both together.
export function altForRoofZ(z) {
  const s = (z - RENDER_TUNE.eh) / Math.max(1e-6, RENDER_TUNE.climbLift);
  if (!(s > 0)) return 0;
  // The curve saturates: `height` is min(1, √(alt/3000)), so the eye stops climbing in z at
  // 3,000 ft. A roof drawn above that could otherwise never be cleared at any altitude.
  return Math.min(3000, 3000 * s * s);
}
// ⚠ THE SAME CURVE READ FOR THE AIRFRAME INSTEAD OF THE EYE, and the two are not the same number.
// `altForRoofZ` answers "at what altitude is my EYE level with this z" — the right question for
// CFIT, and for "can I see over it". It is the WRONG question for standing on something. The chase
// model is anchored at `EHbase - eh` (ownShipBaseWz), so an aircraft's gear rides at
// `climbLift · height` in world-z with no `eh` term in it at all: the eye is a fixed 0.24 z above
// the skids, which on the Solenne's crown is 159 real feet. Park a helicopter at
// `altForRoofZ(deckZ)` and it rests eight storeys down inside the tower with its eye level with the
// deck — which is exactly what it looked like.
//
// Both inverses are the render curve read backwards and neither is a tuning constant: a change to
// `eh` or `climbLift` moves the picture, the collision and the deck together.
export function altRestingOnZ(z) {
  const s = z / Math.max(1e-6, RENDER_TUNE.climbLift);
  if (!(s > 0)) return 0;
  return Math.min(3000, 3000 * s * s);   // saturates with the eye curve — `height` is min(1, √(alt/3000))
}
export function buildingRoofFt(wx, wy, cell) {
  return altForRoofZ(buildingHeightZ(wx, wy, cell));
}

// Roof altitude in FEET at one specific point on a tile — the per-segment counterpart to
// buildingRoofFt, which answers for the whole tile as a single square.
//
// What this fixes. Collision used to be one axis-aligned box of half-width BUILDING_FOOT with its
// roof at floors × 12 ft, and the models draw nothing like that: an office tower extrudes to 1.7×
// its storey stack, Halcyon to 2.9×, and none of those multipliers ever reached the sim — so you
// flew through the top two thirds of the tallest buildings in the city. Meanwhile the bank's
// stylobate is WIDER than the collision square and its attic narrower, so you also clipped mass
// that wasn't there and passed through mass that was. Reading the captured segments makes what you
// hit the thing you can see, including the gap between a tower and its low wing on the same tile.
//
// Returns 0 when the probe is inside no segment — which is now a real answer rather than an
// approximation, and the reason a plaza between two wings is finally flyable.
//
// Deliberately reads the LIVE capture rather than the baked file: models whose shape varies with
// the tile seed (rooftop clutter) collide as they are actually drawn on that tile.
export function buildingRoofFtAt(wx, wy, cell, px, py) { return modelTopAt(wx, wy, cell, px, py, true); }
// The same probe answered in RENDER world-z instead of feet — what the rooftop-helipad guidance
// column needs, since it is drawn in the world frame rather than flown in the altitude frame. One
// loop, one answer: the pad you aim at and the pad you touch down on can never drift apart.
export function modelTopZAt(wx, wy, cell, px, py) { return modelTopAt(wx, wy, cell, px, py, false); }
export function modelTopAt(wx, wy, cell, px, py, inFeet) {
  if (buildingHeightZ(wx, wy, cell) <= 0) return 0;
  // The bay again: `modelFor` would hand back the truck_depot ARM's captured segments, and that arm
  // is not what is on the glass for this tile — the mark branch in drawWorldObjects took it. So the
  // shed answers for its own roof, which is a straight gable and needs no capture at all.
  if (isBay(cell)) {
    const E = faceVec(cell.ent), th = Math.atan2(-E[0], E[1]), ct = Math.cos(th), st = Math.sin(th);
    const ox = px - wx, oy = py - wy;
    const lx = ox * ct + oy * st, ly = -ox * st + oy * ct;
    if (Math.abs(lx) > BAY.HW || Math.abs(ly) > BAY.HL) return 0;
    const z = bayTopZ(lx);
    return inFeet ? altForRoofZ(z) : z;
  }
  const seed = (wx + 512) * 73 + (wy + 512) * 149;
  const m = modelFor(cell);
  const floors = floorsOf(cell);
  const hz = floorHeight(cell, seed);
  if (!m) {
    // No dedicated model (a biome archetype) — the old square, unchanged.
    const foot = BUILDING_FOOT * (RENDER_TUNE.bldgFoot || 1);
    const inBox = Math.abs(px - wx) <= foot && Math.abs(py - wy) <= foot;
    return inBox ? (inFeet ? altForRoofZ(hz) : hz) : 0;
  }
  const segs = shapeForModel(m, seed);
  if (!segs || !segs.length) return inFeet ? altForRoofZ(hz) : hz;
  const h = hz;
  if (!(h > 0)) return 0;
  const fh = (BUILDING_FOOT + frac(seed + 2) * 0.06) * (RENDER_TUNE.bldgFoot || 1);
  // Into the model's own frame: undo the entrance rotation, then per segment undo its yaw.
  const E = faceVec(cell.ent), th = Math.atan2(-E[0], E[1]), ct = Math.cos(th), st = Math.sin(th);
  const ox = px - wx, oy = py - wy;
  const lx = ox * ct + oy * st, ly = -ox * st + oy * ct;
  const V = (p) => p[0] * fh + p[1] * h + p[2];
  // ⚠ RANKED IN WORLD-Z AND CONVERTED ONCE, not per segment. altForRoofZ is monotonic, so the
  // tallest segment in z is the tallest in feet — and doing the conversion inside the loop would
  // run a square per segment per sweep step on the collision hot path for no answer it changes.
  let best = 0;
  for (const s of segs) {
    const top = V(s.z1);
    if (top <= best) continue;                   // can't raise the answer — skip the containment maths
    if (segContains(s, lx, ly, V)) best = top;
  }
  return inFeet ? altForRoofZ(best) : best;
}

// Is a MODEL-LOCAL point inside this segment's footprint? Extracted so the aircraft's CFIT probe
// (modelTopAt) and the ground vehicle's obstruction probe (groundObstructionAt) share one answer.
// They ask different questions — "how high is the mass here" vs "is the mass here in my way" — but
// "is this point in this segment" must be the same test in both, or a truck and a plane will
// disagree about where a building's wall is.
function segContains(s, lx, ly, V) {
  let dx = lx - V(s.cx), dy = ly - V(s.cy);
  if (s.kind === 'box') {
    const f = segFit(s, V);                      // the same clamps draw3DBoxAt applies internally
    dx = lx - f.cx; dy = ly - f.cy;
    if (s.yaw) { const c = Math.cos(-s.yaw), n = Math.sin(-s.yaw); const rx = dx * c - dy * n; dy = dx * n + dy * c; dx = rx; }
    return Math.abs(dx) <= f.hw && Math.abs(dy) <= f.fd;
  }
  if (s.kind === 'drum') {
    const r = Math.max(V(s.rb), V(s.rt));
    return dx * dx + dy * dy <= r * r;
  }
  if (s.kind === 'barrel') return Math.abs(dx - V(s.cxL)) <= V(s.hl) && Math.abs(dy) <= V(s.hw);
  return Math.abs(dx) <= V(s.hx) && Math.abs(dy) <= V(s.hy);
}

// THE MODEL'S SOLID VOLUME, AS A PREDICATE.
//
// ⚠ THE SOLID THE OCCLUSION BAKE SAMPLES IS THE SOLID YOU CRASH INTO, deliberately — this hands
// back `segContains` over the same captured shape that `modelTopAt` and `groundObstructionAt` ask,
// so a corner that reads as dark is a corner that is actually there. A second idea of "inside the
// building" living in the GL pass is the drift this whole capture arrangement exists to prevent.
//
// Resolved once at (fh, h) and handed back closed over, because the caller asks it tens of
// thousands of times per model and the affine solve is most of the work.
export function modelSolid(m, seed, fh, h) {
  const segs = shapeForModel(m, seed);
  if (!segs || !segs.length) return null;
  const V = (q) => q[0] * fh + q[1] * h + q[2];
  const res = segs.map((sg) => ({ sg, z0: V(sg.z0), z1: V(sg.z1) }));
  // ⚠ `only` NARROWS, IT NEVER WIDENS. An occlusion bake asks this tens of thousands of times per
  // model against the same handful of segments, so it passes the indices its own range test already
  // found; every other caller omits it and tests the whole model, exactly as before.
  const hit = (x, y, z, only) => {
    const n = only ? only.length : res.length;
    for (let i = 0; i < n; i++) {
      const r = res[only ? only[i] : i];
      if (z < r.z0 || z > r.z1) continue;
      if (segContains(r.sg, x, y, V)) return true;
    }
    return false;
  };
  // ⚠ A CONSERVATIVE BOX PER SEGMENT, SO A CALLER CAN ASK "IS ANYTHING NEAR" BEFORE IT ASKS "IS
  // THIS SOLID". It must never be SMALLER than the real segment — a caller that skips work on the
  // strength of this would skip it wrongly — so a yawed box takes its own diagonal and a drum takes
  // the larger of its two radii on both axes.
  hit.bounds = res.map(({ sg, z0, z1 }) => {
    let cx = V(sg.cx), cy = V(sg.cy);
    let hx, hy;
    if (sg.kind === 'drum') { hx = hy = Math.max(V(sg.rb), V(sg.rt)); }
    else if (sg.kind === 'barrel') { hx = V(sg.hl) + Math.abs(V(sg.cxL)); hy = V(sg.hw); }
    else if (sg.kind === 'box') {
      const f = segFit(sg, V);
      cx = f.cx; cy = f.cy; hx = f.hw; hy = f.fd;
      if (sg.yaw) { const d = Math.hypot(hx, hy); hx = hy = d; }
    } else { hx = V(sg.hx); hy = V(sg.hy); }
    return { x0: cx - hx, x1: cx + hx, y0: cy - hy, y1: cy + hy, z0, z1 };
  });
  return hit;
}

// GROUND OBSTRUCTION — the ground vehicle's half of CFIT (THE LONG HAUL).
//
// `modelTopAt` answers "how tall is the mass over this point", which is the right question for an
// aircraft: you are above it or you are not. A truck asks a different one — "is there something in
// my way at MY height" — and the difference is `z0`. modelTopAt ignores it entirely, so an
// overhanging attic, a barrel roof, a canopy or a mast reads as solid all the way to the ground.
// Drive under an archway and you would hit a building that is physically over your head.
//
// So: same containment, plus `z0 <= clearZ`. A segment only blocks you if its underside comes down
// to at least your roofline. Returns the blocking segment's TOP in world-z (a useful magnitude for
// "how big a thing did I just hit"), or 0 for clear road.
//
// `clearZ` is the vehicle's height in render world-z. FLOOR_Z is one storey, so a semi tractor at
// roughly a third of a storey is about 0.009.
// A rig rides over anything shorter than this rather than stopping dead on it — the OTHER end of
// the same question `clearZ` asks at the top of the vehicle. Kept out of cab-view.js so the model
// arms that draw a kerb and the sweep that decides whether it is a wall read one number.
//
// This exists because of a forecourt. The pump islands are edged with a kerb, the arm that draws
// them says in as many words that it is low enough to ride over, and it was not: the sweep's only
// test was the segment's UNDERSIDE against the cab roof, and a kerb's underside is the ground. So
// every island on the lot collided as a full-height wall and the one building in the game you are
// supposed to drive into was the one you could not. Deliberately tiny — 0.011 world-z is under 6%
// of a storey, which is a kerb, a threshold or a painted-on lip and nothing else. Anything with
// real mass on it (the pump plinths that stand on these islands, at 10% of a storey) is still a
// thing you hit, and `forecourtDriveSmoke` asserts both halves of that.
export const TRUCK_STEP_Z = 0.011;
export function groundObstructionAt(wx, wy, cell, px, py, clearZ = 0.01, stepZ = 0) {
  // THE CURTAIN, FIRST, BECAUSE EVERY BRANCH BELOW STARTS FROM BUILDING MASS AND IT HAS NONE.
  // `buildingHeightZ` answers 0 on a perimeter tile, so without this the function returns "clear
  // road" for a floor-to-sky sheet of hard light. It goes through the shared probe rather than
  // being tested here, so the wall a rig stops at is the wall the windscreen is drawing. See
  // curtainTopZAt — including why the gate tile is the one that stays open.
  const curZ = curtainTopZAt(wx, wy, cell, px, py);
  if (curZ > 0) return curZ;
  // ⚠ THE ONE HOLE IN A BUILDING, and it is named rather than general: a depot bay is a shed you
  // drive into, so at ground level it is open. Everything about this is deliberately narrow — it
  // is keyed on a mark the world derivation only puts on a tile authored `flags.vehicle_bay`, it
  // applies to the whole tile rather than to a doorway rectangle (a door you can miss by four
  // inches is a door players will hate), and it must never become a general "buildings with doors
  // are passable" rule. A truck is the only thing this matters for; a pedestrian was always able
  // to walk in, because walking in is what an exit is.
  // ⚠ …AND THE HOLE HAS A DOOR IN IT NOW. The tile is still open ground — the walls of this shed
  // have never blocked anything and making them do so is a separate job — but the aperture itself
  // is only a hole while the door is UP. Shut, it is a physical object you stop at, from either
  // side, which is what makes it a door rather than a texture that animates when you get close.
  //
  // Only the threshold plane blocks, not the whole tile: a rig parked at the back of a shed whose
  // door has come down must be able to sit there rather than be trapped inside solid ground. The
  // band is generous (±0.1 tile) because a sweep samples discretely and a door you can tunnel
  // through at fifty is worse than no door at all.
  if (cell?.mark === 'bay') {
    // ⚠ THE DOOR IS READ FROM THE BODY BEING TESTED, NOT FROM THE RENDER FRAME. This asked
    // `bayDoorOpen`, whose occupant list is in the WINDSCREEN's own-ship-relative frame — the own
    // ship sits at (0, 0) there — while `wx, wy` here are world tile coordinates. Two different
    // origins, so the sensor was measuring a rig that did not exist at a shed that was not there,
    // came back zero, and the doorway went solid on the person driving out of it. That is the
    // exit you could not leave through with the door standing open above you.
    //
    // The probe point IS the vehicle, so it can answer for itself: same curve, same constants, fed
    // the one position this function actually knows. And that is also the honest model — a door
    // opens for the thing arriving at it, so approach it and it lifts, come at the wall beside it
    // and it does not.
    const [lx, ly] = bayLocal(px, py, wx, wy, cell);
    if (bayDoorSense(lx, ly) > 0.5) return 0;
    if (Math.abs(lx) <= BAY.DOOR_W + 0.02 && Math.abs(ly - BAY.HL) < 0.10) return BAY.DOOR_H;
    return 0;
  }
  if (buildingHeightZ(wx, wy, cell) <= 0) return 0;
  const seed = (wx + 512) * 73 + (wy + 512) * 149;
  const m = modelFor(cell);
  const hz = floorHeight(cell, seed);
  if (!m) {
    // No dedicated model (a biome archetype): the same plain square modelTopAt falls back to.
    const foot = BUILDING_FOOT * (RENDER_TUNE.bldgFoot || 1);
    return (Math.abs(px - wx) <= foot && Math.abs(py - wy) <= foot) ? hz : 0;
  }
  const segs = shapeForModel(m, seed);
  if (!segs || !segs.length) return hz;          // a model we can't decompose is solid, not a hole
  const h = hz;
  if (!(h > 0)) return 0;
  const fh = (BUILDING_FOOT + frac(seed + 2) * 0.06) * (RENDER_TUNE.bldgFoot || 1);
  const E = faceVec(cell.ent), th = Math.atan2(-E[0], E[1]), ct = Math.cos(th), st = Math.sin(th);
  const ox = px - wx, oy = py - wy;
  const lx = ox * ct + oy * st, ly = -ox * st + oy * ct;
  const V = (p) => p[0] * fh + p[1] * h + p[2];
  let worst = 0;
  for (const s of segs) {
    // The z0 gate, and the whole reason this is not just modelTopAt: a segment whose underside is
    // above the vehicle's roof is something you drive UNDER, not into.
    if (V(s.z0) > clearZ) continue;
    // …and its mirror at the other end: a segment whose TOP is below the vehicle's step-over height
    // is something you drive OVER. Default 0, so every caller that does not opt in behaves exactly
    // as it always did and nothing in the world quietly became passable.
    if (stepZ > 0 && V(s.z1) <= stepZ) continue;
    if (!segContains(s, lx, ly, V)) continue;
    const top = V(s.z1);
    if (top > worst) worst = top;
  }
  return worst;
}
// The widest any model can reach from its tile centre, for a cheap reject before the per-segment
// test. draw3DBoxAt clamps a footprint half-width to 0.44, and offset sub-parts (a forecourt vat, a
// porch post) sit outside that — so this is deliberately generous. Being too big only costs a few
// wasted containment tests; being too small would silently make buildings non-solid at the edges.
export const MODEL_MAX_EXTENT = 1.0;

// Shared climb-out corridor test: a building dead ahead and low, right off the runway, is
// culled from the render entirely (see drawWorldObjects) so it never draws — and per the
// "must be visible to collide" rule, the CFIT sweep in cockpit.js skips the exact same tiles
// via this helper, so a building that isn't drawn can't hurt you either. f = forward distance,
// lat = lateral offset from the flight-path centerline (both in tile units), height = 0..1
// eye-height fraction. Returns false when the renderer would have culled it (corr <= 0).
// Capped to CLIMBOUT_MAX_F tiles ahead so this only shields the immediate runway departure —
// NOT any low pass elsewhere in the city, where buildings collide normally. NOTE: this is now
// a COLLISION-only shield — the renderer always draws these buildings (a building in view never
// disappears), so during climb-out you SEE the departure towers and out-climb them rather than
// them vanishing. 4.5 tiles covers a heavy/jet ground roll (Leviathan, Reaper); a light Mayfly
// is airborne and climbing well inside this, so widening it doesn't cost the lighter craft.
export const CLIMBOUT_MAX_F = 4.5, CLIMBOUT_LAT_IN = 0.3, CLIMBOUT_LAT_OUT = 0.2;
// The renderer's own near/far visibility window (drawWorldObjects) — a building this close
// (about to pass under/behind you) or this far (still fading in) isn't really "on the glass"
// yet. Collision must never fire on a tile outside this window, or a hit can land on
// something the player couldn't actually have seen.
// How near the lens a CONTACT's own geometry may come before that face is dropped — the aircraft
// and the trucks, not the world. Named because the decal painters take a near plane from their
// caller now, and the one thing that must never happen is the artwork and the panel it is printed
// on disappearing at two different distances.
export const CONTACT_NEAR_F = 0.07;
export const VISIBLE_NEAR_F = 0.05, VISIBLE_FAR_F = 34;   // long skyline — buildings draw out to 34 tiles (the server sends a 36-tile map window); only the last HAZE_BAND tiles fade, so the distance reads crisp rather than hazed
export function climbOutClear(f, lat, height) {
  if (!(f > 0.1 && f < CLIMBOUT_MAX_F && height < 0.2)) return true;
  return clamp((Math.abs(lat) - CLIMBOUT_LAT_IN) / CLIMBOUT_LAT_OUT, 0, 1) > 0;
}

const TR = () => Math.max(0.5, TUNE.texRes || 1);
// The neon tone, quantised. See `RENDER_TUNE.neon`. ⚠ `RENDER_TUNE` and not the per-view `TUNE`: a
// baked texture is cached per palette for the life of the process and shared by every seat, so a
// per-view value here would bake whichever view painted first into the canvas the other one reads.
// `texRes` gets away with being per-view only because it is in the cache key AND resizes the canvas.
const NEON_STEPS = 16;
const NQ = () => Math.round(clamp(RENDER_TUNE.neon ?? 1, 0, 1) * NEON_STEPS) / NEON_STEPS;
// ── HOW MUCH DARKER IS THIS SURFACE AFTER DARK? ONE RULE, ONE PLACE. ──────────────────────────
//
// `wallTex` carried six blanket night dims, each a literal alpha chosen for its own branch — 0.40
// for a lattice because it is mostly sky-shaped hole, 0.31 for a plain material, 0.26 for a painted
// panel. Those relative judgements are right and none of them is what `RENDER_TUNE.neon` wants to
// argue with, so the knob DEEPENS EACH IN PROPORTION rather than replacing them with one number. A
// lattice stays the darkest thing on the street at every setting.
//
// ⚠ `base + neon * base * K`, never `base * (1 + neon * K)` written out — same value, but the first
// form makes it obvious by inspection that neon 0 is the literal that was there before.
const NIGHT_DEEPEN = 0.75;
const nightDrop = (base) => base + NQ() * base * NIGHT_DEEPEN;
// ── WHAT COLOUR IS THE LIGHT INSIDE THIS BUILDING? ────────────────────────────────────────────
//
// A lit window is the commonest light in the city and every one of them was the same sodium amber,
// so a bar, a clinic and a chrome boutique all glowed identically and the only thing telling them
// apart after dark was the shape of the box. The models already answer this — 73 of them carry a
// `neon:` accent — and the texture generator cannot see a model, only a palette key. So: one map
// from palette to accent, built from the registry.
//
// ⚠ LAZY, ON FIRST CALL, NOT AT MODULE LOAD — the same rule `wallMaterials()` follows and for the
// same reason: the model tables are declared ~7,000 lines below this, and a module-level build
// would be a TDZ throw that takes the whole client down.
//
// ⚠ ONE TEXTURE PER PALETTE, STILL. The accent is looked up by palette key rather than handed in
// per building, because `wallTex` caches on that key — an accent passed as an argument would mint a
// texture per model and the atlas would stop fitting the 2048 floor it is held to.
let _palNeon = null;
function palNeon(pal) {
  if (!_palNeon) {
    _palNeon = new Map();
    for (const table of [NAMED_MODELS, TYPE_MODEL]) {
      for (const m of Object.values(table || {})) {
        // ⚠ FIRST WRITER WINS, and that is deliberate rather than lazy. `ty_bar_a` and friends are
        // shared by several models; the alternative is blending two accents into a third colour
        // that neither building asked for.
        if (!m || !m.pal || _palNeon.has(m.pal)) continue;
        // ⚠ `accentOf`, not `m.neon` — see the ⚠ on that function. It answers for all 173 models
        // where `m.neon` answers for 73, and the 100 it fills in are exactly the buildings whose
        // windows all burned the same amber as each other.
        // `hexRgb` and `accentOf` are both declared below this line and read at call time, which is
        // a frame, not module evaluation. A malformed accent is skipped rather than throwing.
        const a = accentOf(m);
        if (/^#[0-9a-f]{6}$/i.test(a)) _palNeon.set(m.pal, hexRgb(a));
      }
    }
  }
  return _palNeon.get(pal) || null;
}
