      g.fillStyle = 'rgba(12,16,22,0.16)';
      g.fillRect((bx - 0.04) * S | 0, (by - 0.03) * S | 0, Math.max(2, (bw + 0.08) * S | 0), Math.max(2, (bh + 0.06) * S | 0));
