  // inside the wall it is screwed to, and there is no `faceforward` in the GL shader.
  const RIM = [[-1, 0.96], [1, 0.96], [1, 0.18], [0.86, -0.28], [0.50, -0.76], [0, -1.18],
    [-0.50, -0.76], [-0.86, -0.28], [-1, 0.18]].map(([u, w]) => [u * r, w * r]);
  const lit = opts.lit == null ? 1 : opts.lit;
