  // depth buffer agree about which of them is on top — `wallDisc`'s pupil, at five points.
  const sr = r * (opts.star || 0.60), si = sr * 0.42, sz = r * 0.02;
  const S = (k, rr) => { const t = k * Math.PI / 5; return [Math.sin(t) * rr, Math.cos(t) * rr + sz]; };
  const FRONT = { lift: DETAIL_LIFT * 1.4, cullN: [E[0], E[1]] };
