  // normal, and a ring walked the other way faces into the building it is cut through.
  const dead = night ? 'rgb(12,13,16)' : 'rgb(24,27,31)';
  const FIELD = []; for (let i = 0; i < N * 3; i++) FIELD.push(at(r * 0.90, -i / (N * 3) * 6.2832));
  emitFlat(ctx, cam, FIELD.map(([u, w]) => P(u, 0, w)), dead, alpha, { lift: DETAIL_LIFT * 1.05, cullN: CN });
