      drawFacetDrum(ctx, cam, ix, iy, h * 0.09, h * 0.34, fh * 0.095, fh * 0.085, 9, alpha,
        (f) => 'rgb(' + (108 + f.nl * 52 | 0) + ',' + (82 + f.nl * 38 | 0) + ',' + (50 + f.nl * 24 | 0) + ')', 'rgb(70,52,32)');
