      draw3DBoxAt(ctx, cam, dx, dy, fh * 0.94, plinth, wallTop, pal, seed + 1, night, alpha, false);
      draw3DBoxAt(ctx, cam, dx, dy, fh * 1.02, wallTop, cornice, 'ty_tomb', seed + 2, night, alpha, true);
