      if (frontVis) for (const [i, t] of [[0, -1], [1, 1]]) {
        const [dx2, dy2] = F(t * fh * (0.34 + i * 0.04), fh * 0.78);
        draw3DBoxAt(ctx, cam, dx2, dy2, fh * 0.30, 0, doorTop * 0.94, 'ty_hulls_door', seed + 4 + i, night, alpha, true, 0, fh * 0.07);
      }
