      if (frontVis) marqueeBand(ctx, cam, dx, dy, E, scSgnW, scSgnZ, m.neon || '#5fd0ff', night, alpha, 'BATTERY ACID', scRoom);
      if (night) { const [wx, wy] = F(0, fh * 0.94); glowPool(ctx, cam, wx, wy, h * 0.22, '255,205,150', 12, alpha * 0.30); }
