      { const [bx, byy] = F(fh * 0.50, fh * 0.88); draw3DBoxAt(ctx, cam, bx, byy, fh * 0.30, h * 0.07, h * 0.10, 'ty_oc_board_dk', seed + 5, night, alpha, true, faceYaw(E), fh * 0.07); }
