      { const [wx, wy] = F(fh * 0.30, fh * 0.62); draw3DBoxAt(ctx, cam, wx, wy, fh * 0.28, h * 0.22, h * 0.46, 'ty_sole_glass', seed + 2, night, alpha, false, faceYaw(E), fh * 0.05); }
