      { const [sx5, sy5] = F(0, fh * 0.95); draw3DBoxAt(ctx, cam, sx5, sy5, fh * 0.86, 0, h * 0.02, pal, seed + 5, night, alpha, true, faceYaw(E), fh * 0.05); }
