    const A = P(-1, -1, hx0, hy0, z0), B = P(1, -1, hx0, hy0, z0), C = P(1, 1, hx0, hy0, z0), D = P(-1, 1, hx0, hy0, z0);
    const E = P(-1, -1, hx1, hy1, z1), F = P(1, -1, hx1, hy1, z1), G = P(1, 1, hx1, hy1, z1), H = P(-1, 1, hx1, hy1, z1);
